function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4000);}
function checkpoint(){history.push(structuredClone(project));if(history.length>100)history.shift();future=[];updateUndo();}
function resetClipHistory(){history=[];future=[];selectedDrawing=null;activeDrawingGroup=null;editorTools?.clear();updateUndo();}
