function loadImage(src){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('Image could not load'));i.src=src;});}
function makeCanvas(w,h){const c=document.createElement('canvas');c.width=w;c.height=h;return c;}
