 try{const closed=await loadImage('assets/drafts/dhanuka-blink-reference.png');assets.dhanuka.blinkClosed=referenceSprite(composeBlinkReference(sourceImage,closed),character('dhanuka').crop);}catch{toast('Blink artwork could not load.');}
