function thumb(sprite){return sprite.toDataURL('image/png');}
function renderCards(){const root=$('characterCards');root.replaceChildren();for(const ch of CHARACTERS){const added=project.cast.some(a=>a.charId===ch.id),b=document.createElement('button');b.className='character-card'+(added?' added':'');b.dataset.character=ch.id;b.setAttribute('aria-label',`${added?'Select':'Add'} ${ch.name}`);const img=new Image();img.className='character-thumb';img.src=thumb(assets[ch.id].original);img.alt=ch.name;const text=document.createElement('span'),strong=document.createElement('strong'),small=document.createElement('small'),plus=document.createElement('span');strong.textContent=ch.name;small.textContent=ch.description;plus.className='add-symbol';plus.textContent=added?'✓':'+';text.append(strong,small);b.append(img,text,plus);b.onclick=()=>addCharacter(ch.id);root.append(b);} $('addAll').disabled=CHARACTERS.every(c=>project.cast.some(a=>a.charId===c.id));}
function addCharacter(charId){stop();const existing=project.cast.find(a=>a.charId===charId);if(existing){selected=existing.id;refresh();return;}if(project.cast.length>=50){toast('Character limit reached.');return;}checkpoint();const a=createActor(charId,Math.min(2,project.cast.length));project.cast.push(a);selected=a.id;markChanged();refresh();}
function addAll(){stop();checkpoint();for(const ch of CHARACTERS)if(project.cast.length<50&&!project.cast.some(a=>a.charId===ch.id))project.cast.push(createActor(ch.id,Math.min(2,project.cast.length)));selected=project.cast[0]?.id;markChanged();refresh();}
function formatTime(t){const min=Math.floor(t/60),sec=t%60;return `${String(min).padStart(2,'0')}:${sec.toFixed(1).padStart(4,'0')}`;}
function setTime(t,{pause=true,snap=true}={}){if(pause)stop();time=Math.max(0,Math.min(project.duration,t));if(actor()?.manualAnimation&&!drawingOpen){if(snap)time=frameTime(frameNumber(time,actor().manualFps),actor().manualFps);if(pause){poseEditMode=true;updateToolMode();}}updateTime();draw();updateInspector();}
function updateTime(){updateManualBar();$('timeDisplay').replaceChildren(document.createTextNode(formatTime(time)+' '));const em=document.createElement('em');em.textContent='/ '+formatTime(project.duration);$('timeDisplay').append(em);for(const p of document.querySelectorAll('.playhead'))p.style.left=`${time/project.duration*100}%`;for(const k of document.querySelectorAll('.key'))k.classList.toggle('active',Math.abs(Number(k.dataset.time)-time)<(actor()?.manualAnimation ? .5/(actor().manualFps||24) : .05));}
function timeFromPointer(e,el){return Math.max(0,Math.min(project.duration,(e.clientX-el.getBoundingClientRect().left)/el.getBoundingClientRect().width*project.duration));}
function addPlayhead(el){const p=document.createElement('div');p.className='playhead';el.append(p);}
function rulerScrub(el){el.onpointerdown=e=>{if(e.target.closest('.key'))return;el.setPointerCapture(e.pointerId);const run=ev=>setTime(Math.round(timeFromPointer(ev,el)*10)/10);run(e);el.onpointermove=run;el.onpointerup=()=>{el.onpointermove=null;};el.onpointercancel=()=>{el.onpointermove=null;};};}
