 document.querySelector('.inspector').append(panel);const ribbon=document.createElement('div');ribbon.id='paintRibbon';ribbon.hidden=true;ribbon.append($('drawingTools'));document.querySelector('.canvas-wrap').before(ribbon);
 for(const [id,label]of DRAW_TOOLS){const b=document.createElement('button');b.textContent=label;b.dataset.drawTool=id;b.onclick=()=>{drawingTool=id;curvePending=id==='curve'&&(project.drawings||[]).find(o=>o.id===selectedDrawing)?.type==='curve'?selectedDrawing:null;if(id!=='select')selectedDrawing=null;updateDrawingControls();draw();};$('drawingTools').append(b);}
 for(const color of ['#18232d','#ffffff','#888888','#ef5350','#b91c1c','#ff8a24','#f4c76b','#ffff00','#66bb6a','#166534','#42a5f5','#1747ae','#ab70d6','#ff86b5','#784b2b','#f1cfaa']){const b=document.createElement('button');b.style.background=color;b.title=color;b.setAttribute('aria-label','Use '+color);b.onclick=()=>{$('drawColor').value=color;$('drawFill').value=color;applyDrawingStyle();};$('drawingPalette').append(b);}
