 for(const [id,property]of [['drawingTurn','rotation'],['drawingScale','scale']])$(id).onchange=()=>{const g=selectedDrawingPart();if(!g)return;checkpoint();putDrawingKey(g,time,{[property]:Number($(id).value)});markChanged();draw();};
