 const parents=$('drawingParent'),parentSignature=signature+JSON.stringify([...invalid]);if(parents.dataset.signature!==parentSignature){parents.replaceChildren(new Option('None — whole animal',''));for(const q of groups)if(!invalid.has(q.id))parents.add(new Option(q.name,q.id));parents.dataset.signature=parentSignature;}parents.value=g?.parentId||'';
 for(const id of ['drawingPartName','drawingParent','assignDrawingPart','drawingPivot','drawingAddKey','drawingDeleteKey','drawingTurn','drawingScale','drawingHold','drawingDeletePart'])$(id).disabled=!g;
 if(document.activeElement!==$('drawingPartName'))$('drawingPartName').value=g?.name||'';
 if(document.activeElement!==$('drawingFrame'))$('drawingFrame').value=frameNumber(time,24);$('drawingFrame').max=frameNumber(project.duration,24);
 if(g){const p=drawingPose(g,time);if(document.activeElement!==$('drawingTurn'))$('drawingTurn').value=p.rotation;if(document.activeElement!==$('drawingScale'))$('drawingScale').value=p.scale;$('drawingTurnValue').textContent=Math.round(p.rotation)+'°';$('drawingScaleValue').textContent=Math.round(p.scale*100)+'%';$('drawingHold').checked=!!g.hold;}
 const keys=$('drawingPoseKeys'),ks=JSON.stringify(g?.keys.map(k=>k.time)||[])+activeDrawingGroup;if(keys.dataset.signature!==ks){keys.replaceChildren();for(const k of g?.keys||[]){const b=document.createElement('button');b.textContent='◇ '+frameNumber(k.time,24);b.title='Go to saved pose';b.onclick=()=>setTime(k.time);keys.append(b);}keys.dataset.signature=ks;renderTimeline();}
