function applyCamera(){const frame=canvas.parentElement;frame.style.transform='translate('+cameraPan.x+'px,'+cameraPan.y+'px) scale('+cameraZoom+')';frame.dataset.previewZoom=cameraZoom.toFixed(3);if($('previewZoom')){const custom=$('customZoom');custom?.remove();const value=String(cameraZoom);if(![...$('previewZoom').options].some(o=>o.value===value)){const o=document.createElement('option');o.id='customZoom';o.value=value;o.textContent=Math.round(cameraZoom*100)+'%';$('previewZoom').append(o);}$('previewZoom').value=value;}}
