function setupAdvancedEditor(){setupAppearanceControls();setupRainControls();editorTools=installEditorTools({addBackground:id=>{showTab('scene');[...$('backgrounds').children].find(b=>b.dataset.background===id)?.click();},renderBackground:(preview,src)=>{loadImage(src).then(img=>{const g=preview.getContext('2d');g.fillStyle='#d4e8ea';g.fillRect(0,0,preview.width,preview.height);const size=Math.min(preview.width/img.width,preview.height/img.height);g.drawImage(img,(preview.width-img.width*size)/2,(preview.height-img.height*size)/2,img.width*size,img.height*size);}).catch(()=>{});},addRain:()=>{checkpoint();project.weather={...DEFAULT_RAIN};markChanged();refresh();showTab('scene');$('rainSettings').open=true;toast('Rain added · press Play. Scene → Rain changes the effect.');},renderWeather:preview=>{const g=preview.getContext('2d');g.fillStyle='#243846';g.fillRect(0,0,preview.width,preview.height);drawRain(g,{...DEFAULT_RAIN,opacity:1},.5,'back');},project:()=>project,time:()=>time,playing:()=>playing,isDrawing:()=>drawingOpen,tool:()=>drawingTool,activeGroup:()=>activeDrawingGroup,setActiveGroup:id=>{activeDrawingGroup=id;},actor:()=>actor(),actorPose:()=>actor()?sampleActor(actor(),time):null,actorBox:()=>hitboxes.find(b=>b.id===selected),selectedDrawing:()=>selectedDrawing,selectDrawing:id=>{selectedDrawing=id;},setTool:id=>{drawingTool=id;updateDrawingControls();},point:e=>{const a=stagePoint(e);return [a.x/canvas.width,a.y/canvas.height];},newClip:requestNewClip,openClip:()=>$('projectInput').click(),exportClip:()=>$('exportBtn').click(),saveClip:()=>saveClipCopy(),blocked:()=>exporting||clipBusy||!!document.querySelector('dialog[open]'),stop,checkpoint,changed:markChanged,refresh,draw,update:updateDrawingControls,toast,showDraw:()=>showTab('draw'),validateDrawings,patchActor:patch=>{if(actor()){putTransformKey(actor(),time,patch);updateInspector();draw();}},pasteActors:actors=>{if(project.cast.length+actors.length>50){toast('Character limit reached.');return;}checkpoint();const copies=structuredClone(actors);for(const a of copies){a.id=uid();for(const k of a.keys){k.x=Math.min(200,k.x+3);k.y=Math.min(200,k.y+2);}for(const c of a.clips)c.id=uid();}project.cast.push(...copies);selected=copies[0]?.id||null;markChanged();refresh();},removeActors:ids=>{checkpoint();project.cast=project.cast.filter(a=>!ids.includes(a.id));selected=project.cast[0]?.id||null;markChanged();refresh();},undo:()=>$('undoBtn').click(),redo:()=>$('redoBtn').click(),seek:value=>setTime(value,{snap:false}),zoom:factor=>{const r=canvas.getBoundingClientRect();zoomStage(cameraZoom*factor,r.left+r.width/2,r.top+r.height/2);},listAssets:async()=>{if(!db)return [];return new Promise((resolve,reject)=>{const list=[],tx=db.transaction('projects'),q=tx.objectStore('projects').openCursor();q.onsuccess=()=>{const c=q.result;if(c){if(String(c.key).startsWith('asset:'))list.push(c.value);c.continue();}};tx.oncomplete=()=>resolve(list);tx.onerror=()=>reject(tx.error);});},saveAsset:async asset=>{if(!db)throw Error('Browser storage unavailable');return new Promise((resolve,reject)=>{const tx=db.transaction('projects','readwrite');tx.objectStore('projects').put(asset,'asset:'+asset.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});},renderItem:(preview,data,sw,sh)=>{const g=preview.getContext('2d');g.fillStyle='#e8e7df';g.fillRect(0,0,preview.width,preview.height);g.save();g.translate(48,48);g.scale(2,2);g.translate(-48,-48);drawObjects(g,data.drawings,'back',null,true,data.groups,0);drawObjects(g,data.drawings,'front',null,true,data.groups,0);g.restore();}});}
async function init(){try{await loadAssets();try{db=await openDB();const saved=await readSaved();if(saved){project=validateProject(saved);const meta=await storageGet('currentMeta');clipIdentity=meta?.clipIdentity||uid();savedClipSignature=meta?.savedClipSignature||'';}else project.cast=CHARACTERS.map((c,i)=>createActor(c.id,i));}catch{project.cast=CHARACTERS.map((c,i)=>createActor(c.id,i));$('saveStatus').textContent='Use Save project to keep your work';}selected=project.cast.find(a=>a.charId==='dhanuka')?.id||project.cast[0]?.id||null;await syncBackground();syncAudio();wireUI();setupEditorLayout();setupClipWorkflow();setupAdvancedEditor();renderMotions();refresh();updateUndo();if(db)persist();requestAnimationFrame(frame);}catch(e){$('emptyStage').replaceChildren();const p=document.createElement('p');p.textContent='Could not load the character reference. Please launch with Start TND Studio.cmd. '+e.message;$('emptyStage').append(p);}}
init();




